    cv.width=W*dpr; cv.height=H*dpr;
    bg=document.createElement('canvas'); bg.width=cv.width; bg.height=cv.height; const g=bg.getContext('2d'); g.scale(dpr,dpr);
    const lg=g.createLinearGradient(0,0,0,H); [[0,'#cbb4ff'],[.1,'#a37bff'],[.26,'#7438f4'],[.48,'#5115d6'],[.72,'#3a0ca8'],[1,'#22077a']].forEach(([o,c])=>lg.addColorStop(o,c)); g.fillStyle=lg; g.fillRect(0,0,W,H);
    [[.5,-.08,.45,'#f1e8ff',.45],[.2,.55,.32,'#8a4dff',.35],[.82,.5,.32,'#7d44ff',.35]].forEach(([x,y,r,c,a])=>{
      const R=Math.max(W,H)*r, rg=g.createRadialGradient(W*x,H*y,0,W*x,H*y,R); rg.addColorStop(0,c); rg.addColorStop(1,c+'00'); g.globalAlpha=a; g.fillStyle=rg; g.fillRect(0,0,W,H); });
    g.globalAlpha=1;
    
    const step=W<640?6:7; dots=[]; let i=0;
    for(let y=step/2;y<H;y+=step) for(let x=step/2;x<W;x+=step){ i++; const f=field(x/W,y/H), r=rnd(i); const b=(0.05+0.7*Math.pow(f,1.8))*(0.3+0.7*r)*(0.35+0.4*y/H); if(b<.03) continue; dots.push([x,y,b,rnd(i*3.7)*6.283,r>.985]); }
