/* --- 1.2 spread --- */
(function(){
  const st={cat:'All categories', you:null, plan:'All plans'};
  const note=()=>{ $('#spreadNote').textContent='Adapty, 2026. View → paid, percent of paywall viewers.'+(st.plan!=='All plans'?` ${st.plan} plans only.`:''); };
  seg($('#spreadPlan'), PLANS, st.plan, v=>{st.plan=v; note(); draw(); res();});
  fillSel($('#spreadCat'), ['All categories',...CATS], st.cat, v=>{st.cat=v; draw(); res();});
  const box=$('#spread');
  $('#youIn').addEventListener('input',e=>{ const v=parseFloat(String(e.target.value).replace(',','.')); st.you = isFinite(v)&&v>=0 ? v : null; draw(); res(); });
  function bucket(v,d){ if(v>=d[3]) return ['top 10%','var(--teal)']; if(v>=d[2]) return ['top 25%','var(--teal)']; if(v>=d[0]) return ['above median','var(--ink)']; if(v>=d[1]) return ['below median','var(--muted)']; return ['bottom 25%','var(--coral)']; }
  function res(){ const el=$('#youRes'); if(st.you==null){ el.innerHTML=''; return; }
    el.innerHTML = REG.map(r=>{ const d=D.v2p[st.plan][r][st.cat]; const [b,c]=bucket(st.you,d); return `<div><b>${r}</b><em style="color:${c}">${b}</em>, median ${p(d[0])}</div>`; }).join(''); }
  function draw(){
    const W=box.clientWidth, mob=W<520, L=mob?62:84, R=mob?14:24, top=34, rowH=mob?54:60, H=top+REG.length*rowH+26+(st.you!=null?26:0), AX=top+REG.length*rowH+26;
    const rows=REG.map(r=>({r, d:D.v2p[st.plan][r][st.cat]}));
    const usMed=rows[0].d[0]; let max=Math.max(...rows.map(o=>o.d[3]), st.you||0)*1.08; const step=max>8?2:1; max=Math.ceil(max/step)*step;
    const sx=v=>L+(W-L-R)*v/max;
    box.innerHTML=''; const svg=S('svg',{class:'svgc',viewBox:`0 0 ${W} ${H}`,width:W,height:H,role:'img','aria-label':'Spread of view to paid conversion by region'},box);
    for(let v=0; v<=max; v+=step){ S('line',{x1:sx(v),x2:sx(v),y1:top-6,y2:AX-24,class:'grid'},svg); T(svg,sx(v),AX-6,v+'%',{'text-anchor':'middle'}); }
    rows.forEach((o,i)=>{ const y=top+i*rowH+rowH/2, d=o.d;
      T(svg,0,y+4,o.r,{class:'lbl'});
      const g=S('g',{'data-tip':`<div class="t-h">${o.r}, ${esc(st.cat)}</div><div class="t-r"><span>Bottom 25% below</span><b>${p(d[1])}</b></div><div class="t-r"><span>Median</span><b>${p(d[0])}</b></div><div class="t-r"><span>Top 25% from</span><b>${p(d[2])}</b></div><div class="t-r"><span>Top 10% from</span><b>${p(d[3])}</b></div><div class="t-r"><span>Top 10% vs median</span><b>${x(d[3]/d[0])}</b></div>`},svg);
      S('rect',{x:L,y:y-16,width:W-L-R,height:32,fill:'transparent'},g);
      S('line',{x1:sx(d[2]),x2:sx(d[3]),y1:y,y2:y,stroke:css('--violet'),'stroke-width':1.5,'stroke-dasharray':'2 3'},g);
      S('rect',{x:sx(d[1]),y:y-10,width:Math.max(2,sx(d[2])-sx(d[1])),height:20,fill:css('--lilac')},g);
      S('rect',{x:sx(d[0])-1.5,y:y-13,width:3,height:26,fill:css('--ink')},g);
      S('circle',{cx:sx(d[3]),cy:y,r:6,fill:css('--violet')},g);
      const beat=d[3]>usMed && o.r!=='US';
      T(g,sx(d[3])+(mob?0:10),mob?y-12:y+4,p(d[3]),{class:'val','text-anchor':mob?'middle':'start',style:beat?`fill:${css('--violet')}`:''});
    });
    const ux=sx(usMed); S('line',{x1:ux,x2:ux,y1:top-10,y2:AX-24,class:'ref'},svg);
    T(svg,Math.min(ux,W-R-4),top-16,`US median ${p(usMed)}`,{class:'reft','text-anchor':ux>W-140?'end':'middle'});
    if(st.you!=null){ const yx=sx(st.you); S('line',{x1:yx,x2:yx,y1:top-6,y2:H-20,stroke:css('--teal'),'stroke-width':2.5},svg); S('rect',{x:yx-34,y:H-20,width:68,height:20,fill:css('--teal')},svg); T(svg,yx,H-6,'You '+p(st.you),{'text-anchor':'middle',style:'fill:#fff;font-weight:600'}); }
  }
  reg(box, draw);
})();

/* --- 1.3 trend --- */
(function(){
  const st={mode:'pct', hl:null}; const box=$('#line');
  seg($('#lineMode'), [['pct','Conversion, %'],['ratio','US vs. region, ×']], st.mode, v=>{st.mode=v; st.hl=null; $('#lineCardTitle').textContent = v==='pct'?'Median paywall view → paid conversion by region, FY24–FY26':'US conversion vs. each region, FY24–FY26'; $('#lineTitle').textContent= v==='pct'?'Median view → paid, %':'US median ÷ region median'; legend(); draw();});
  function series(){ return st.mode==='pct' ? REG.map(r=>({r, v:D.fy[r]})) : ['Europe','APAC','LATAM','MEA'].map(r=>({r, v:D.fyRatio[r]})); }
  function legend(){ $('#lineLegend').innerHTML = series().map(s=>{ const ch=st.mode==='pct' ? Math.round((s.v[2]/s.v[0]-1)*100) : null; return `<button type="button" data-r="${s.r}" style="border:0;background:none;padding:4px 0;cursor:pointer;display:inline-flex;align-items:center;gap:7px;color:var(--muted);font-size:13px;opacity:${st.hl&&st.hl!==s.r?.4:1}"><i style="display:inline-block;width:14px;height:3px;border-radius:2px;background:${rc(s.r)}"></i>${s.r}${ch!=null?` <b style="color:${ch<0?'var(--coral)':'var(--teal)'};font-weight:600">${ch>0?'+':''}${ch}%</b>`:''}</button>`; }).join('');
    $('#lineLegend').querySelectorAll('button').forEach(b=>b.onclick=()=>{ st.hl= st.hl===b.dataset.r?null:b.dataset.r; legend(); draw(); }); }
  function draw(){
    const W=box.clientWidth, mob=W<520, L=36, R=mob?96:124, top=16, H=mob?280:340, B=30, ser=series();
    const fmt = st.mode==='pct' ? (v=>p(v)) : (v=>x(v));
    let max=Math.max(...ser.flatMap(s=>s.v)); const step = st.mode==='pct'?1:1; max=Math.ceil(max*1.08/step)*step;
    const sx=i=>L+(W-L-R)*(i/2), sy=v=>top+(H-top-B)*(1-v/max);
    box.innerHTML=''; const svg=S('svg',{class:'svgc',viewBox:`0 0 ${W} ${H}`,width:W,height:H,role:'img','aria-label':'Two-year trend by region'},box);
    for(let v=0; v<=max; v+=step){ S('line',{x1:L,x2:W-R+10,y1:sy(v),y2:sy(v),class:'grid'},svg); T(svg,L-8,sy(v)+4,st.mode==='pct'?v+'%':v+'×',{'text-anchor':'end'}); }
    if(st.mode==='ratio'){ S('line',{x1:L,x2:W-R+10,y1:sy(1),y2:sy(1),class:'ref'},svg); T(svg,L+4,sy(1)-6,'Same as US',{class:'reft'}); }
    ['FY24','FY25','FY26'].forEach((f,i)=>T(svg,sx(i),H-8,f,{'text-anchor':i===0?'start':i===2?'end':'middle',style:'font-weight:600'}));
    ser.forEach(s=>{ const op=st.hl&&st.hl!==s.r?.15:1, col=css(RVAR[s.r]);
      S('polyline',{points:s.v.map((v,i)=>sx(i)+','+sy(v)).join(' '),fill:'none',stroke:col,'stroke-width':s.r==='US'?3:2.5,'stroke-linejoin':'round',opacity:op},svg);
      s.v.forEach((v,i)=>S('circle',{cx:sx(i),cy:sy(v),r:i===2?5:3.5,fill:i===2?col:css('--surface'),stroke:col,'stroke-width':2,opacity:op,'data-fy':i,'data-r':i===2?5:3.5,class:'fyd',style:'transition:r .15s ease'},svg)); });
    // end labels with collision avoidance
    const ls=ser.map(s=>({r:s.r,y:sy(s.v[2]),v:s.v[2]})).sort((a,b)=>a.y-b.y); const gapY=mob?15:17;
    for(let i=1;i<ls.length;i++) if(ls[i].y-ls[i-1].y<gapY) ls[i].y=ls[i-1].y+gapY;
    for(let i=ls.length-2;i>=0;i--) if(ls[i].y>ls[i+1].y-gapY) ls[i].y=ls[i+1].y-gapY;
    ls.forEach(l=>{ const op=st.hl&&st.hl!==l.r?.25:1; const t=T(svg,W-R+12,l.y+4,'',{opacity:op}); const a=S('tspan',{style:`fill:${css(RVAR[l.r])};font-weight:700`},t); a.textContent=fmt(l.v); const b=S('tspan',{dx:5},t); b.textContent=l.r; });
    // hover columns: highlight the period under the cursor
    const guide=S('line',{y1:top,y2:H-B,stroke:css('--line-2'),'stroke-width':1,style:'opacity:0;transition:opacity .15s'},svg); svg.insertBefore(guide, svg.querySelector('polyline'));
    [0,1,2].forEach(i=>{ const cx=sx(i), w=(W-L-R)/2; const tipH=`<div class="t-h">${['FY24','FY25','FY26'][i]}</div>`+ser.map(s=>`<div class="t-r"><span>${s.r}</span><b>${fmt(s.v[i])}</b></div>`).join('');
      const hit=S('rect',{x:Math.max(L-10,cx-w/2),y:top,width:i===1?w:w/2+10,height:H-top-B,fill:'transparent','data-tip':tipH},svg);
      const on=()=>{ guide.setAttribute('x1',cx); guide.setAttribute('x2',cx); guide.style.opacity=1; svg.querySelectorAll('.fyd').forEach(c=>c.setAttribute('r', +c.dataset.fy===i ? +c.dataset.r+3 : c.dataset.r)); };
      const off=()=>{ guide.style.opacity=0; svg.querySelectorAll('.fyd').forEach(c=>c.setAttribute('r',c.dataset.r)); };
      hit.addEventListener('pointerenter',on); hit.addEventListener('pointerleave',off); hit.addEventListener('click',on); });
  }
  legend(); reg(box, draw);
})();

