/* assisted scroll (desktop): a short wheel gesture = one smooth move to the next / previous slide;
   continued fast spinning chains further slides. Long slides scroll natively until their end. */
(function(){
  const still=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const desk=matchMedia('(min-width:961px) and (pointer:fine)');
  const SEL='.cover, #chapters, #ch1 > .opener, #ch2 > .opener, #ch3 > .opener, #ch4 > .opener, #ch5 > .opener, .thesis, .take, .promo-sec, .next, .cta-sec, .quote-sec, .skill-sec, .facts-sec';
  const OFF=44;                                   // section top sits just under the sticky header
  let anim=0, animating=false, lastWheel=0;
  const ease=t=>1-Math.pow(1-t,3);
  function go(to,dur){ const from=scrollY, d=to-from; if(Math.abs(d)<2) return; if(anim) cancelAnimationFrame(anim);
    dur=dur||Math.min(700,Math.max(420,Math.abs(d)*0.6)); const t0=performance.now(); animating=true;
    const step=now=>{ const k=Math.min(1,(now-t0)/dur); window.scrollTo({top:from+d*ease(k),behavior:'instant'}); if(k<1) anim=requestAnimationFrame(step); else { anim=0; animating=false; } };
    anim=requestAnimationFrame(step); }
  // slides with their top (snap point) and the bottom of their content (the last thing that must be seen)
  function slides(){ const y=scrollY, maxY=document.documentElement.scrollHeight-innerHeight, seen=new Set(), out=[];
    document.querySelectorAll(SEL).forEach(e=>{ const r=e.getBoundingClientRect(), raw=Math.round(r.top+y);
      const top=Math.max(0,Math.min(maxY, e.classList.contains('cover')?raw:raw-OFF)); if(seen.has(top)) return; seen.add(top);
      const inner=e.querySelector(':scope > .wrap')||e, bot=Math.round(inner.getBoundingClientRect().bottom+y)+28;   // content bottom + a little air
      out.push({top, bot}); });
    return out.sort((p,q)=>p.top-q.top); }
  function targets(){ return slides().map(s=>s.top); }
  // gesture state: a quick flick = one step; keeping the wheel spinning chains further slides
  const STEP=220, GAP=260;
  let gDir=0, gAcc=0, goal=null;
  function nextFrom(pos,dir,T){ if(dir>0){ const n=T.find(t=>t>pos+2); return n==null?null:n; } const p=[...T].reverse().find(t=>t<pos-2); return p==null?null:p; }
  // one step never skips part of a slide: if the current slide continues below the screen, reveal it first
  function stepFrom(y,dir){ const S=slides(), vh=innerHeight, maxY=document.documentElement.scrollHeight-vh; if(!S.length) return null;
    let i=0; S.forEach((s,k)=>{ if(s.top<=y+2) i=k; }); const cur=S[i];
    if(dir>0){
      if(cur.bot > y+vh+4) return Math.min(maxY, cur.bot-vh, y+Math.round(vh*.85));      // rest of this slide (footer) first
      return S[i+1] ? S[i+1].top : null; }
    if(y>cur.top+2) return Math.max(cur.top, y-Math.round(vh*.85));                       // back to the top of this slide first
    const prev=S[i-1]; if(!prev) return null;
    return (prev.bot-prev.top > vh+4) ? Math.max(prev.top, prev.bot-vh) : prev.top;        // tall previous slide: land on its end
  }
  // trackpads (many small, pixel-precise deltas with momentum) get plain native scrolling; mouse wheels keep slide-by-slide paging
  let padUntil=0;
  function looksLikeTrackpad(e){
    if(e.deltaMode!==0) return false;                                    // line/page deltas = classic mouse wheel
    if(Math.abs(e.deltaX)>0.5) return true;                              // any sideways movement = two-finger swipe
    const w=e.wheelDeltaY;
    if(typeof w==='number' && w!==0) return Math.abs(w)%120!==0;          // mouse notches report multiples of 120
    return !Number.isInteger(e.deltaY) || Math.abs(e.deltaY)<40;          // fallback: fractional or tiny steps
  }
  addEventListener('wheel',e=>{
    const now0=performance.now();
    if(looksLikeTrackpad(e)) padUntil=now0+1200;
    if(now0<padUntil){ if(anim){ cancelAnimationFrame(anim); anim=0; animating=false; } return; }   // free scroll while the gesture lasts
    if(still || !desk.matches || e.ctrlKey || Math.abs(e.deltaY)<Math.abs(e.deltaX)) return;
    const now=performance.now(), dir=Math.sign(e.deltaY); if(!dir) return;
    const fresh = now-lastWheel>GAP || dir!==gDir;
    lastWheel=now;
    if(fresh){
      gDir=dir; gAcc=0;
      const to=stepFrom(scrollY,dir); if(to==null) return;                               // page edge: let the browser handle it
      e.preventDefault(); goal=to; go(to); return;
    }
    e.preventDefault();
    gAcc+=Math.abs(e.deltaY);
    let moved=false;
    while(gAcc>=STEP){ gAcc-=STEP; const n=stepFrom(goal??scrollY,dir); if(n==null||n===goal) break; goal=n; moved=true; }
    if(moved) go(goal, Math.min(650,Math.max(380,Math.abs(goal-scrollY)*0.35)));
  },{passive:false});
  ['mousedown','touchstart','keydown'].forEach(ev=>addEventListener(ev,()=>{ if(anim){ cancelAnimationFrame(anim); anim=0; animating=false; } },{passive:true}));
  // anchor links (menu, header, CTA): same smooth move
  document.addEventListener('click',e=>{ const a=e.target.closest('a[href^="#"]'); if(!a) return; const t=document.querySelector(a.getAttribute('href')); if(!t) return; e.preventDefault();
    const y=Math.round(t.getBoundingClientRect().top+scrollY); go(Math.max(0, t.id==='top'?0:y-OFF)); history.replaceState(null,'',a.getAttribute('href')); });
})();

