/* 3.1 anatomy: phone in the centre, 4 labels each side, connectors to the exact element */
(function(){
  const box=$('#anat'), phone=$('#anPhone'), svgEl=$('#anLines'), labs=[...box.querySelectorAll('.anat-list li')];
  function draw(){
    const W=box.clientWidth, wide=W>=300, compact=W<560; box.classList.toggle('wide',wide); box.classList.toggle('compact',compact);
    labs.forEach(l=>{ l.style.cssText=''; }); svgEl.innerHTML=''; if(!wide){ box.style.height=''; return; }
    // narrow cards: the phone keeps its design size (220px) and is scaled as a whole, so its proportions never change
    if(compact){ const k=Math.min(1,(W*0.42)/220); phone.style.width='220px'; phone.style.transformOrigin='top center'; phone.style.transform=`scale(${k})`; phone.style.marginBottom=`${-(220*852/393)*(1-k)}px`; }
    else { phone.style.width=phone.style.transform=phone.style.transformOrigin=phone.style.marginBottom=''; }
    const B=box.getBoundingClientRect(), P=phone.getBoundingClientRect();
    const pl=P.left-B.left, pr=P.right-B.left, gap=compact?12:30, colW=Math.max(compact?64:120,pl-gap);
    const pt=(k,side)=>{ const r=box.querySelector(`[data-an="${k}"]`).getBoundingClientRect(); return {x:(side==='l'?r.left:r.right)-B.left+(side==='l'?-1:1)*0, y:r.top-B.top+r.height/2}; };
    const out={l:[],r:[]};
    labs.forEach(l=>{ const side=l.dataset.side, t=pt(l.dataset.k,side);
      l.style.width=colW+'px'; l.style.left=(side==='l'?0:pr+gap)+'px'; out[side].push({l,t,h:l.offsetHeight}); });
    let H=P.height;   // P is the scaled box
    ['l','r'].forEach(side=>{ const a=out[side].sort((p,q)=>p.t.y-q.t.y);
      // each label sits on its element's line; only when two would collide do they spread apart (both ways), never squeezed to the top
      a.forEach(o=>o.top=o.t.y-10);
      for(let it=0;it<60;it++){ let moved=false;
        for(let k=0;k<a.length-1;k++){ const p=a[k],q=a[k+1],need=p.top+p.h+8-q.top; if(need>0.5){ p.top-=need/2; q.top+=need/2; moved=true; } }
        if(a.length&&a[0].top<0){ const d=-a[0].top; a.forEach(o=>o.top+=d); }
        if(!moved) break; }
      a.forEach(o=>{ o.l.style.top=o.top+'px'; H=Math.max(H,o.top+o.h); }); });
    box.style.height=Math.max(P.height,H)+'px';
    const C=css('--lilac-2'), D=css('--violet'); let h='';
    // connector: straight horizontal when the label sits on the element's line; otherwise an orthogonal route (horizontal → vertical riser → horizontal).
    // the line stops 6px before the element and never crosses it.
    ['l','r'].forEach(side=>out[side].forEach(o=>{ const ay=o.top+10, ax= side==='l' ? colW+8 : pr+gap-8, ex= side==='l' ? pl-12 : pr+12, tx= side==='l' ? o.t.x-6 : o.t.x+6, ty=o.t.y;
      // straight when the label is on the element's line; otherwise a single bend: down/up beside the label, then straight in
      const straight = ty>=o.top && ty<=o.top+o.h-4;   // the element's line passes through the label block
      const pts = straight ? `${ax},${ty} ${tx},${ty}` : `${ax},${ay} ${ax},${ty} ${tx},${ty}`;
      h+=`<polyline points="${pts}" fill="none" stroke="#1e0c45" stroke-opacity=".55" stroke-width="1" stroke-dasharray="4 4" stroke-linejoin="round"/>`; }));   // Figma: thin dashed leaders, no end dots
    svgEl.innerHTML=h;
  }
  // small screens: labels show only their names; tap a name to read the stat
  labs.forEach(l=>l.addEventListener('click',e=>{ if(!box.classList.contains('compact')) return; e.stopPropagation(); const on=!l.classList.contains('on'); labs.forEach(x=>x.classList.remove('on')); if(on) l.classList.add('on'); }));
  document.addEventListener('click',()=>labs.forEach(x=>x.classList.remove('on')));
  draw(); let w=box.clientWidth; new ResizeObserver(()=>{ if(box.clientWidth!==w){ w=box.clientWidth; draw(); } }).observe(box);
  addEventListener('load',draw);
})();

/* chapter openers: faint blue pixel field on the side margins, fading toward the text (rhymes with the cover) */
(function(){
  const still=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const rnd=i=>{ const x=Math.sin(i*12.9898)*43758.5453; return x-Math.floor(x); };
  const field=(xn,yn)=>Math.max(0,Math.min(1,.5+.22*Math.sin(xn*5.3+yn*2.1+.7)+.18*Math.sin(xn*11.7-yn*6.3+2.2)+.12*Math.sin(xn*23.1+yn*13.7+4.1)));
  const sm=(a,b,x)=>{ const t=Math.max(0,Math.min(1,(x-a)/(b-a))); return t*t*(3-2*t); };
  document.querySelectorAll('.opener').forEach((op,k)=>{
    const cv=op.querySelector('.op-px'), ctx=cv.getContext('2d'); let W=0,H=0,dpr=1,dots=[],vis=false,last=0;
    function build(){ dpr=Math.min(2,devicePixelRatio||1); W=op.clientWidth; H=op.clientHeight; if(!W||!H) return; cv.width=W*dpr; cv.height=H*dpr;
      const wrap=op.querySelector('.wrap').getBoundingClientRect(), R=op.getBoundingClientRect(), x0=wrap.left-R.left+24, step=W<640?6:7; dots=[]; let i=k*7919;
      // soft spots near the text: one behind the end of the heading, one low in the middle (below the content)
      const tr=el=>{ const g=document.createRange(); g.selectNodeContents(el); return g.getBoundingClientRect(); };
      const hr=tr(op.querySelector('h2')), ir=tr(op.querySelector('.idea')), mob=W<640;
      const spots=[{x:hr.right-R.left-(mob?40:70), y:hr.top-R.top+hr.height*.5, r:mob?120:190, a:.8},      // behind the end of the heading
                   {x:Math.min(W-40, ir.right-R.left+(mob?20:140)), y:ir.top-R.top+ir.height*.45, r:mob?110:170, a:.6},  // beside the paragraph
                   {x:W*.5, y:H-(mob?22:30), r:W*(mob?.42:.24), a:.9}];                                   // low in the middle, under the content
      const sw=(x,y)=>Math.max(...spots.map(p=>p.a*Math.exp(-(((x-p.x)**2+((y-p.y)*1.4)**2)/(p.r*p.r)))));
      for(let y=step/2;y<H;y+=step){ const vy=sm(0,H*.18,y)*sm(H,H*.82,y);
        for(let x=step/2;x<W;x+=step){ i++;
          const wl=1-sm(x0*.15, x0+60, x);                       // left margin, gone just past the text edge
          const wr=sm(W*.62, W*.98, x);                           // right side, away from the text column
          const wgt=Math.max(Math.max(wl,wr)*vy, sw(x,y)); if(wgt<.02) continue;
          const f=field(x/W+k*.37,y/H), r=rnd(i), b=wgt*(0.2+0.9*Math.pow(f,1.5))*(0.3+0.7*r); if(b<.03) continue;
          dots.push([x,y,b,rnd(i*3.7)*6.283,r>.988]); } }
      draw(0); }
    function draw(t){ ctx.setTransform(dpr,0,0,dpr,0,0); ctx.clearRect(0,0,W,H); const s=W<640?1.4:1.6, tt=t/1000;
      for(const [x,y,b,ph,hot] of dots){ const wave=.6+.4*Math.sin(x*.006-tt*.5+y*.004), tw=.65+.35*Math.sin(tt*(1.1+ph*.3)+ph); let a=b*wave*tw; if(hot) a=Math.min(.7,a*2.2+.1);
        ctx.fillStyle=`rgba(${hot?'70,80,225':'92,104,235'},${a.toFixed(3)})`; ctx.fillRect(x,y,s,s); } }
    function loop(t){ if(!vis){ setTimeout(()=>loop(performance.now()),250); return; } requestAnimationFrame(loop); if(t-last<80) return; last=t; draw(t); }
    build(); if(!still) requestAnimationFrame(loop);
    new IntersectionObserver(e=>{ vis=e[0].isIntersecting; }).observe(op);
    let w=0,h=0; new ResizeObserver(()=>{ if(Math.abs(op.clientWidth-w)>2||Math.abs(op.clientHeight-h)>2){ w=op.clientWidth; h=op.clientHeight; build(); } }).observe(op);
  });
})();

/* square opener art: on desktop the illustration is absolutely positioned, so the opener reserves its height */
(function(){
  function hold(){ document.querySelectorAll('.opener .wrap').forEach(w=>{ const ill=w.querySelector('.op-ill'); if(!ill) return;
    w.style.minHeight=''; if(getComputedStyle(ill).position!=='absolute') return;
    const top=parseFloat(getComputedStyle(ill).top)||0; w.style.minHeight=Math.ceil(ill.getBoundingClientRect().height+top)+'px'; }); }
  hold(); addEventListener('resize',hold); document.fonts&&document.fonts.ready.then(hold);
})();

/* keep a clear gap between an opener illustration and the block below it (e.g. "Where users drop") */
(function(){
  const GAP=48;
  function fit(){ document.querySelectorAll('.opener .wrap').forEach(w=>{ const ill=w.querySelector('.op-ill'), j=w.querySelector('.journey'); if(!ill||!j) return;
    j.style.marginTop=''; if(getComputedStyle(ill).display==='none') return;
    const need=ill.getBoundingClientRect().bottom+GAP-j.getBoundingClientRect().top; if(need>0) j.style.marginTop=(parseFloat(getComputedStyle(j).marginTop)+need)+'px'; }); }
  fit(); addEventListener('resize',fit); document.fonts&&document.fonts.ready.then(fit);
})();

