  pairs('#t52',[['Localization',62.3,44.9],['Trial',59.6,39.9],['Plan duration',58.7,37.8],['Number of plans',57.1,46.1],['Price',45.5,28.3],['Visual / text only',34.6,31.4]],62.3,v=>Math.round(v)+'%');
