const bar=$('#bar'), prog=$('#prog'), secNav=$('#secNav'), curCh=$('#curCh'); let navFor=null;
const chsw=$('#chsw'), chswMenu=$('#chswMenu');
function buildSwitch(id){ const ids=Object.keys(NAV);
  chswMenu.innerHTML=ids.map((k,i)=>`<a role="menuitem" href="#${k}" class="${k===id?'cur':''}"><i>${i+1}</i>${NAV[k][0]}</a>`).join(''); }
function closeSw(){ chsw.classList.remove('open'); curCh.setAttribute('aria-expanded','false'); }
curCh.addEventListener('click',e=>{ e.stopPropagation(); const o=chsw.classList.toggle('open'); curCh.setAttribute('aria-expanded',o); });
document.addEventListener('click',e=>{ if(!chsw.contains(e.target)) closeSw(); });
chswMenu.addEventListener('click',e=>{ if(e.target.closest('a')) closeSw(); });
addEventListener('keydown',e=>{ if(e.key==='Escape') closeSw(); });
function buildNav(id){ if(navFor===id) return; navFor=id; const [t,items]=NAV[id]; curCh.textContent=t; buildSwitch(id);
  secNav.innerHTML=items.map(([h,n,l])=>`<a href="#${h}" title="${l}">${n}<span>&nbsp;${l}</span></a>`).join(''); }
function onScroll(){ const y=scrollY, hero=$('#top').offsetHeight; bar.classList.toggle('on', y>hero*0.7);
  const chs=[...document.querySelectorAll('section.chapter')]; let cur=chs[0];
  chs.forEach(c=>{ if(c.getBoundingClientRect().top<innerHeight*0.4) cur=c; });
  buildNav(cur.id);
  const r=cur.getBoundingClientRect(), s=y+r.top, e=s+cur.offsetHeight-innerHeight; prog.style.width=Math.max(0,Math.min(1,(y-s)/(e-s)))*100+'%';
  let a=null; secNav.querySelectorAll('a').forEach(l=>{ const t=document.querySelector(l.getAttribute('href')); if(t && t.getBoundingClientRect().top<innerHeight*0.4) a=l; });
  secNav.querySelectorAll('a').forEach(l=>l.classList.toggle('cur',l===a)); }
addEventListener('scroll',onScroll,{passive:true}); onScroll();

