/* methodology: "+" opens the full card in an overlay over the grid; ×, a click outside the card or Esc closes it */
(function(){ const grid=document.querySelector('.mt-grid'); if(!grid) return; const pop=grid.querySelector('.mt-pop'), body=pop.querySelector('.mt-body');
  function open(k){ const c=grid.querySelector(`.mt-card[data-k="${k}"]`); body.innerHTML=c.querySelector('.mt-ico').outerHTML+`<h4>${c.querySelector('h4').innerHTML.replace(/<br\s*\/?>/g,'')}</h4>`+`<div class="mt-txt">${c.querySelector('.mt-txt').innerHTML}</div>`; pop.hidden=false; pop.querySelector('.mt-close').focus({preventScroll:true}); }
  function close(){ pop.hidden=true; }
  grid.addEventListener('click',e=>{ const b=e.target.closest('.mt-more'); if(b){ open(b.dataset.mt); return; } if(e.target.closest('.mt-close') || e.target===pop) close(); });
  addEventListener('keydown',e=>{ if(e.key==='Escape' && !pop.hidden) close(); });
})();

/* opener illustrations: parallax on pointer hover — every illustration is split into explicit layers (<g class="pl" data-d>),
   each layer drifts by its own depth, so objects move relative to each other */
(function(){
  if(!matchMedia('(hover:hover) and (pointer:fine)').matches || matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const MAX=10, items=[];
  document.querySelectorAll('svg.op-ill').forEach(svg=>{
    const layers=[...svg.querySelectorAll('g.pl')].map(g=>({g,d:parseFloat(g.dataset.d)||0}));
    if(!layers.length) return;
    layers.forEach(l=>{ l.g.style.willChange='transform'; });
    items.push({svg,layers,tx:0,ty:0,x:0,y:0});
  });
  if(!items.length) return;
  let raf=0;
  function tick(){ raf=0; let moving=false;
    items.forEach(it=>{ it.x+=(it.tx-it.x)*.08; it.y+=(it.ty-it.y)*.08;
      if(Math.abs(it.tx-it.x)>.002||Math.abs(it.ty-it.y)>.002) moving=true;
      it.layers.forEach(l=>{ l.g.style.transform=`translate(${(it.x*MAX*l.d).toFixed(2)}px,${(it.y*MAX*l.d).toFixed(2)}px)`; }); });
    if(moving) raf=requestAnimationFrame(tick); }
  addEventListener('pointermove',ev=>{
    items.forEach(it=>{ const r=it.svg.getBoundingClientRect();
      const inside=r.width && ev.clientX>=r.left && ev.clientX<=r.right && ev.clientY>=r.top && ev.clientY<=r.bottom;
      it.tx=inside? ((ev.clientX-r.left)/r.width-.5)*2 : 0; it.ty=inside? ((ev.clientY-r.top)/r.height-.5)*2 : 0; });
    if(!raf) raf=requestAnimationFrame(tick); }, {passive:true});
  document.addEventListener('pointerleave',()=>{ items.forEach(it=>{it.tx=0; it.ty=0;}); if(!raf) raf=requestAnimationFrame(tick); });
})();

/* cover on phones: tall 3:4 crop around the title, with the inner edges of the left and right tile columns shown as narrow strips at the sides */
(function(){ const box=document.querySelector('#top .cv13'), svg=box&&box.querySelector('.fsvg'); if(!svg) return; const full=svg.getAttribute('viewBox')||'0 0 1472 828'; const mq=matchMedia('(max-width:900px)');
  const NS='http://www.w3.org/2000/svg'; const art=document.getElementById('cvArt');
  // each strip gets real copies of only the tiles it shows (a <use> of the whole artwork renders some fills black on iOS/Chrome)
  const strip=(side,x0,x1)=>{ const s=document.createElementNS(NS,'svg'); s.setAttribute('class','cv-side '+side); s.setAttribute('aria-hidden','true'); s.setAttribute('preserveAspectRatio','xMidYMid slice'); s.setAttribute('fill','none');
    const g=document.createElementNS(NS,'g'); [...art.children].forEach(k=>{ if(k.tagName==='rect'){ g.appendChild(k.cloneNode(true)); return; } if(k.tagName!=='g') return; let b; try{ b=k.getBBox(); }catch(e){ return; } if(b.x<x1&&b.x+b.width>x0&&b.width<700) g.appendChild(k.cloneNode(true)); });
    s.appendChild(g); g.querySelectorAll('[filter]').forEach(n=>n.removeAttribute('filter')); g.querySelectorAll('foreignObject').forEach(n=>n.remove()); box.insertBefore(s,svg.nextSibling); return s; };
  let L=null,R=null; const S=30;
  const apply=()=>{ if(!mq.matches){ svg.setAttribute('viewBox',full); svg.style.left=svg.style.right=''; if(L){L.style.display=R.style.display='none';} return; }
    if(!L){ L=strip('l',150,260); R=strip('r',1215,1330); } L.style.display=R.style.display='block';
    const W=box.clientWidth, H=box.clientHeight||W*4/3, k=H/828, su=S/k, cu=(W-2*S)/k;
    svg.style.left=S+'px'; svg.style.right=S+'px'; svg.setAttribute('viewBox',`${(736-cu/2).toFixed(1)} 0 ${cu.toFixed(1)} 828`);
    L.setAttribute('viewBox',`${(252-su).toFixed(1)} 0 ${su.toFixed(1)} 828`); R.setAttribute('viewBox',`1222 0 ${su.toFixed(1)} 828`); };
  apply(); mq.addEventListener('change',apply); new ResizeObserver(apply).observe(box); })();
(function(){ return; const svg=document.querySelector('#top .cv13 .fsvg'); if(!svg) return; const full=svg.getAttribute('viewBox')||'0 0 1472 828'; const mq=matchMedia('(max-width:900px)');
  const apply=()=>{ svg.setAttribute('viewBox', mq.matches ? '425 0 621 828' : full); }; apply(); mq.addEventListener('change',apply); })();
