(function(){ const el=document.getElementById('t51'); if(!el) return; const fit=()=>{ const W=el.clientWidth; const t=Math.max(7,Math.min(20,Math.floor(W/28.2))); el.style.setProperty('--t',t+'px'); el.style.setProperty('--g',Math.max(2,Math.round(t/5))+'px'); }; fit(); new ResizeObserver(fit).observe(el); })();
/* cover: one twinkling pixel grid on the open background (replaces the static pixels baked into the cover artwork) */
(function(){ const box=document.querySelector('#top .cv13'); if(!box) return; const svg=box.querySelector('.fsvg'), root=svg&&svg.querySelector(':scope > g'); if(!root) return;
  const cv=document.createElement('canvas'); cv.className='cv-px'; cv.setAttribute('aria-hidden','true'); box.appendChild(cv); const ctx=cv.getContext('2d');
  const still=matchMedia('(prefers-reduced-motion: reduce)').matches; let W=0,H=0,dpr=1,dots=[],vis=true,last=0;
  const rnd=i=>{const x=Math.sin(i*127.1+311.7)*43758.5453; return x-Math.floor(x)};
  const fld=(a,b)=>Math.max(0,Math.min(1,.5+.24*Math.sin(a*6.1+b*2.7+.4)+.2*Math.sin(a*13.3-b*7.1+1.9)+.12*Math.sin(a*27.7+b*15.3+3.3)));
  // every small square in the artwork's root layer is a baked pixel: hide them all, the canvas draws the grid instead
  const sq=/^M[\d.]+ [\d.]+H[\d.]+V[\d.]+H[\d.]+V[\d.]+Z$/;
  const baked=[...root.children].filter(k=>k.tagName==='path'&&sq.test(k.getAttribute('d')||'')&&k.getBBox().width<3);
  baked.forEach(p=>p.style.display='none');
  const bgRects=[...root.children].filter(k=>k.tagName==='rect');
  const CV_MASK={"w":184,"h":104,"m":["",""]};
  const cvBits=CV_MASK.m.map(s=>s&&Uint8Array.from(atob(s),c=>c.charCodeAt(0))); let cvQ=null;
  const cvPrep=()=>{ const bk=root.querySelector('.cv-bk'), bits=cvBits[bk&&getComputedStyle(bk).display==='none'?1:0], m=svg.getScreenCTM();
    cvQ=bits&&m?{bits,inv:m.inverse(),S:svg.getBoundingClientRect()}:null; };
  const openBg=(px,py)=>{ if(!cvQ){ const el=document.elementFromPoint(px,py); return !!el&&bgRects.includes(el); }
    const {bits,inv:v,S}=cvQ; if(px<S.left||px>=S.right||py<S.top||py>=S.bottom) return false;
    const j=Math.round((v.a*px+v.c*py+v.e-1)/8), i=Math.round((v.b*px+v.d*py+v.f-1)/8), n=i*CV_MASK.w+j;
    return j>=0&&i>=0&&j<CV_MASK.w&&i<CV_MASK.h&&(bits[n>>3]>>(n&7)&1)===1; };
  function build(){ cvPrep(); const B=box.getBoundingClientRect(); dpr=Math.min(2,devicePixelRatio||1); W=B.width; H=B.height; if(!W||!H) return; cv.width=W*dpr; cv.height=H*dpr; dots=[]; let i=0;
    const m=svg.getScreenCTM(); const k=m?m.a:1, step=8*k, s=Math.max(2,Math.round(1.6*k*dpr))/dpr;
    const ox=m?((m.e-B.left)%step+step)%step:0, oy=m?((m.f-B.top)%step+step)%step:0;      // grid aligned to the artwork's own 8-unit grid
    for(let y=oy;y<H;y+=step) for(let x=ox;x<W;x+=step){ i++;
      if(!openBg(B.left+x+1,B.top+y+1)) continue;   // only the open background
      const cx=(x/W-.5)/.42, cy=(y/H-.47)/.42, centre=Math.max(0,1-Math.sqrt(cx*cx+cy*cy));
      const f=fld(x/W,y/H)*(.55+.6*centre); if(f<.36) continue;
      const r=rnd(i), a=(.05+.34*Math.pow(Math.min(1,(f-.36)/.5),1.3))*(.4+.6*r); if(a<.05) continue;
      dots.push([Math.round(x*dpr)/dpr,Math.round(y*dpr)/dpr,a,rnd(i*3.7)*6.283,r>.985,s]); }
    draw(0); }
  function draw(t){ ctx.setTransform(dpr,0,0,dpr,0,0); ctx.clearRect(0,0,W,H); const tt=t/1000;
    for(const [x,y,a0,ph,hot,s] of dots){ const wave=.6+.4*Math.sin(x*.006-tt*.6+y*.004), tw=.6+.4*Math.sin(tt*(1.2+ph*.3)+ph); let a=Math.min(.6,a0*(.75+1.2*wave*tw)); if(hot) a=Math.min(.9,a*2.4+.2);
      ctx.fillStyle=`rgba(${hot?'255,255,255':'214,196,255'},${a.toFixed(3)})`; ctx.fillRect(x,y,s,s); } }
  function loop(t){ if(!vis){ setTimeout(()=>loop(performance.now()),250); return; } requestAnimationFrame(loop); if(t-last<66) return; last=t; draw(t); }
  const start=()=>{ build(); if(!still) requestAnimationFrame(loop); };
  if(document.readyState==='complete') setTimeout(start,50); else addEventListener('load',()=>setTimeout(start,50));
  new IntersectionObserver(e=>{ vis=e[0].isIntersecting; }).observe(box);
  let w=0,h=0; new ResizeObserver(()=>{ if(Math.abs(box.clientWidth-w)>2||Math.abs(box.clientHeight-h)>2){ w=box.clientWidth; h=box.clientHeight; build(); } }).observe(box);
})();

